function validateEntity(obj, spec) {
  const issues = [];
  for (const [k, rule] of Object.entries(spec)) {
    const v = obj[k];
    if (v === undefined) { issues.push('missing:' + k); continue; }
    if (rule === 'enum' && !['billing', 'shipping', 'returns'].includes(v)) issues.push('bad-enum:' + k);
    if (rule === 'score' && (typeof v !== 'number' || v < 0 || v > 1)) issues.push('bad-range:' + k);
  }
  return issues.length ? { ok: false, issues } : { ok: true };
}
const spec = { category: 'enum', confidence: 'score' };
console.log(JSON.stringify(validateEntity({ category: 'shipping', confidence: 0.9 }, spec)));
console.log(JSON.stringify(validateEntity({ category: 'Exchange', confidence: 0.9 }, spec)));
console.log(JSON.stringify(validateEntity({ category: 'billing' }, spec)));

